// Party configuration
// Supports dynamic loading from the ledger API (falls back to static config)

export interface PartyInfo {
  displayName: string;
  partyId: string;
  role: string;
}

// Static fallback (auto-generated by update-parties.js or start.sh)
const staticParties: Record<string, PartyInfo> = {
  alice: {
    displayName: 'Alice',
    partyId: 'party-cd107aae-b900-4303-90aa-15da97458a6c::12200e6e03f67665df76af6b94fb81d38605cd44cfdeb3c515dda4d0081d9106ee78',
    role: 'User'
  },
  bob: {
    displayName: 'Bob',
    partyId: 'party-1f42efa3-a7d6-44fb-9dc6-a50c65a7b0dd::12200e6e03f67665df76af6b94fb81d38605cd44cfdeb3c515dda4d0081d9106ee78',
    role: 'User'
  },
  bank: {
    displayName: 'Bank',
    partyId: 'party-41d77386-a4aa-4bcf-a06d-821b1188c55f::12200e6e03f67665df76af6b94fb81d38605cd44cfdeb3c515dda4d0081d9106ee78',
    role: 'Issuer'
  }
};

// Dynamic parties loaded from the ledger at runtime
let dynamicParties: Record<string, PartyInfo> | null = null;

// Fetch current party IDs from the backend (cors-proxy /api/parties endpoint)
export async function loadParties(baseUrl: string): Promise<Record<string, PartyInfo>> {
  try {
    const url = `${baseUrl.replace(/\/+$/, '')}/api/parties`;
    const res = await fetch(url);
    if (res.ok) {
      dynamicParties = await res.json();
      console.log('Loaded dynamic party IDs from ledger:', dynamicParties);
      return dynamicParties!;
    }
    console.warn('Failed to load parties from API, using static config');
  } catch (e) {
    console.warn('Could not reach parties API, using static config:', e);
  }
  return staticParties;
}

function getParties(): Record<string, PartyInfo> {
  return dynamicParties || staticParties;
}

export const getPartyByName = (name: string): PartyInfo | undefined => {
  return getParties()[name.toLowerCase()];
};

export const getDisplayName = (partyId: string): string => {
  const party = Object.values(getParties()).find(p => p.partyId === partyId);
  return party?.displayName || partyId.split('::')[0];
};

export const getAllParties = (): PartyInfo[] => {
  return Object.values(getParties());
};
